mapper.select:
SELECT pet_allowed
  FROM fairs
 WHERE fair_id = #{fairId}

SELECT pa.pet_id , pa.allergy_type_id , pat.label , pat.requires_text , pa.other_text FROM pet_allergies pa JOIN pet_allergy_types pat ON pat.allergy_type_id = pa.allergy_type_id WHERE pa.pet_id IN
#{petId}
ORDER BY FIELD(pat.category, 'FOOD', 'ENVIRONMENT', 'OTHER'), pat.sort_order, pat.allergy_type_id

SELECT rpa.reservation_pet_id , rpa.allergy_type_id , pat.code , pat.category , pat.label , pat.requires_text , rpa.other_text_snapshot FROM reservation_pet_allergies rpa JOIN pet_allergy_types pat ON pat.allergy_type_id = rpa.allergy_type_id WHERE rpa.reservation_pet_id IN
#{reservationPetId}
ORDER BY FIELD(pat.category, 'FOOD', 'ENVIRONMENT', 'OTHER'), pat.sort_order, pat.allergy_type_id
